;Тексты диалогов;Формат диалога:;"TXT",0 - конец диалога;"TXT",1 - перевод на собеседника;"TXT",2 - перевод на гл. героя;"TXT",3,X - переход на другой диалог и конец текущ. диалога;"TXT",4,X - выполнение скрипта под номером X и конец диалога;"TXT",5,X - выполнение скрипта X, который возвращ. в HL адрес; след. диалога, при A'=0 героя, A'<>0 собеседника;Т.е. может служить для продолжения речи какого-либо героя;"TXT",13- перевод на строку ниже;длина строки 34 симв. в диалоге;КомандыEND     EQU 0SOBES   EQU 1HERO    EQU 2DIALOG  EQU 3SCRPT   EQU 4NEXT    EQU 6 ;продолжение диалога любого персонажа              ;нужно когда весь диалог не влезает в окно диалогаCR      EQU 13;перевод строкиPL      EQU #C000 ;реальное местоположение текстовFA      EQU #7000 ;куда компилируемSM=-FA+PL        ORG FA;Провидец ГлебGL_     DW G0+SM,G1+SM ;ссылки на диалогG0      DB "Возьмите, может сгодится.",SOBES        DB "Вещи - это оковы, которые тянут",CR        DB "человека к земле...",ENDG1      DB "Здравствуйте, молодой человек.",SOBES        DB "Приветствую вас, Вера!",HERO        DB "Вы, должно быть, Глеб?",SOBES        DB "Да, зовут меня Глеб. Хотя все",CR        DB "кличут Провидцем, потому как",CR        DB "считают, что я будущее вижу.",HERO        DB "А на самом деле, не так что ли?",SOBES        DB "Нет, я вижу суть вещей!",HERO        DB "Вроде мне это и надо. Загляни-ка",CR        DB "в эту самую ""суть"", и скажи,",CR        DB "кто это тут безобразничает?",SOBES        DB "Так, где мой хрустальный шар...",CR        DB "Оммммм...",HERO        DB "Что ты видишь?",SOBES        DB "Вижу око!",HERO        DB "Что?",SOBES        DB "Тьфу ты! Не тот канал. Уммммм...",HERO        DB "...Удобная, наверное, штука...",SOBES        DB "Точно! Особенно в пятницу",CR        DB "вечером... Вот!",HERO        DB "Что?",SOBES        DB "Вижу колдуна... Имя... Зловет!",CR        DB "Железная палка в руке. Злой",CR        DB "наверно.",HERO        DB "Что он делает?",SOBES        DB "Колокол ворует... Вот гад! И чары",CR        DB "какие-то напускает на все вокруг.",CR        DB "Ай!",HERO        DB "Что?!",SOBES        DB "Камеру видеонаблюдения разбил,",CR        DB "негодяй!",HERO        DB "Ну, в общем, все ясно. Надо",CR        DB "наказать нахала... Поможешь мне?",SOBES        DB "А я разве уже не помог?",HERO        DB "Эх, молодежь! Ну, прощай...",SOBES        DB "Прощай, Вера! Удачи тебе!",SCRPT,60GEND        INCLUDE "02ZLOVET"        INCLUDE "03HEVOR"        INCLUDE "04BUKVIN"        INCLUDE "05JORA"        INCLUDE "06PETRO"        INCLUDE "07ALENA"        INCLUDE "08FEKLA"        INCLUDE "09ZADOL"        INCLUDE "0AREPLIC"ObjTab=$        ORG ObjTab        DB "GLEB    t"        DW GL_        DW GEND-GL_        DB 16        DB "xt"        DB "ZLOVET  t"        DW ZL_        DW ZLEND-ZL_        DB 16        DB "xt"        DB "HEVOR   t"        DW HV_        DW HEND-HV_        DB 16        DB "xt"        DB "BUKVIN  t"        DW BK_        DW BEND-BK_        DB 16        DB "xt"        DB "JORA    t"        DW JR_        DW JEND-JR_        DB 16        DB "xt"        DB "PETRO   t"        DW PE_        DW PEND-PE_        DB 16        DB "xt"        DB "ALENA   t"        DW AL_        DW AEND-AL_        DB 16        DB "xt"        DB "FEKLA   t"        DW FK_        DW FEND-FK_        DB 16        DB "xt"        DB "ZADOLB  t"        DW ZD_        DW ZEND-ZD_        DB 16        DB "xt"        DB "REPLIC  t"        DW REPLIC        DW REND-REPLIC        DB 16        DB "xt"        DB 0 ;END        ORG #6100        INCLUDE "SAVEOBJ4"        ORG #6100        DISPLAY "Gleb=   ",GEND-GL_        DISPLAY "Zlovet= ",ZLEND-ZL_        DISPLAY "Hevor=  ",HEND-HV_        DISPLAY "Bukvin= ",BEND-BK_        DISPLAY "Jora=   ",JEND-JR_        DISPLAY "Petro=  ",PEND-PE_        DISPLAY "Alena=  ",AEND-AL_        DISPLAY "Fekla=  ",FEND-FK_        DISPLAY "Kuznec= ",ZEND-ZD_        DISPLAY "Replic= ",REND-REPLIC        DISPLAY "В сумме=",REND-GL_